create table if not exists public.catalog_aluminum (id bigint generated always as identity primary key, system text not null default '', code text not null default '', name text not null default '', unit text not null default 'Thanh', color text not null default '', weight_kg numeric not null default 0, price numeric not null default 0);
create table if not exists public.catalog_accessories (id bigint generated always as identity primary key, system text not null default '', code text not null default '', name text not null default '', unit text not null default 'Cái', grp text not null default '', price numeric not null default 0);
create table if not exists public.customers (id bigint generated always as identity primary key, code text not null default '', name text not null default '', phone text not null default '', address text not null default '', note text not null default '');
create index if not exists catalog_aluminum_code_idx on public.catalog_aluminum (code);
create index if not exists catalog_accessories_code_idx on public.catalog_accessories (code);
alter table public.catalog_aluminum enable row level security;
drop policy if exists catalog_aluminum_sel on public.catalog_aluminum; create policy catalog_aluminum_sel on public.catalog_aluminum for select to authenticated using (true);
drop policy if exists catalog_aluminum_ins on public.catalog_aluminum; create policy catalog_aluminum_ins on public.catalog_aluminum for insert to authenticated with check (public.is_boss());
drop policy if exists catalog_aluminum_upd on public.catalog_aluminum; create policy catalog_aluminum_upd on public.catalog_aluminum for update to authenticated using (public.is_boss()) with check (public.is_boss());
drop policy if exists catalog_aluminum_del on public.catalog_aluminum; create policy catalog_aluminum_del on public.catalog_aluminum for delete to authenticated using (public.is_boss());
alter table public.catalog_accessories enable row level security;
drop policy if exists catalog_accessories_sel on public.catalog_accessories; create policy catalog_accessories_sel on public.catalog_accessories for select to authenticated using (true);
drop policy if exists catalog_accessories_ins on public.catalog_accessories; create policy catalog_accessories_ins on public.catalog_accessories for insert to authenticated with check (public.is_boss());
drop policy if exists catalog_accessories_upd on public.catalog_accessories; create policy catalog_accessories_upd on public.catalog_accessories for update to authenticated using (public.is_boss()) with check (public.is_boss());
drop policy if exists catalog_accessories_del on public.catalog_accessories; create policy catalog_accessories_del on public.catalog_accessories for delete to authenticated using (public.is_boss());
alter table public.customers enable row level security;
drop policy if exists customers_sel on public.customers; create policy customers_sel on public.customers for select to authenticated using (true);
drop policy if exists customers_ins on public.customers; create policy customers_ins on public.customers for insert to authenticated with check (public.is_boss());
drop policy if exists customers_upd on public.customers; create policy customers_upd on public.customers for update to authenticated using (public.is_boss()) with check (public.is_boss());
drop policy if exists customers_del on public.customers; create policy customers_del on public.customers for delete to authenticated using (public.is_boss());

alter table public.quotes add column if not exists status text not null default 'draft';
alter table public.quotes add column if not exists exported_at timestamptz;
alter table public.quotes add column if not exists exported_by text;

